// Package dashboard serves the files produced by make dashboard.
package dashboard

import (
	"archive/tar"
	"bytes"
	"compress/gzip"
	"crypto/sha256"
	_ "embed"
	"fmt"
	"io"
	"mime"
	"net/http"
	"path"
	"strconv"
	"strings"
)

//go:embed "generated by make dashboard/assets.tar"
var bundle []byte

type representation struct {
	body []byte
	etag string
}

func represent(body []byte) representation {
	return representation{body: body, etag: fmt.Sprintf(`"%x"`, sha256.Sum256(body))}
}

type Asset struct {
	plain, gzip             representation
	mediaType, cacheControl string
}

var files = loadAssets()

func loadAssets() map[string]*Asset {
	files := make(map[string]*Asset)
	tr := tar.NewReader(bytes.NewReader(bundle))
	for {
		header, err := tr.Next()
		if err == io.EOF {
			return files
		}
		if err != nil {
			panic(err)
		}
		zipped, err := io.ReadAll(tr)
		if err != nil {
			panic(err)
		}
		zr, err := gzip.NewReader(bytes.NewReader(zipped))
		if err != nil {
			panic(err)
		}
		raw, err := io.ReadAll(zr)
		if err != nil {
			panic(err)
		}
		zr.Close()
		route := "/" + header.Name
		if route == "/index.html" {
			route = "/"
		}
		media := mime.TypeByExtension(path.Ext(header.Name))
		if media == "" {
			media = "application/octet-stream"
		}
		cache := "no-cache"
		if header.PAXRecords["BIRDWATCH.cache"] == "immutable" {
			cache = "private, max-age=31536000, immutable"
		}
		files[route] = &Asset{plain: represent(raw), gzip: represent(zipped), mediaType: media, cacheControl: cache}
	}
}

// Lookup uses only exact paths emitted by the build.
func Lookup(path string) *Asset { return files[path] }

func acceptsGzip(values []string) bool {
	wildcard := false
	for _, token := range strings.Split(strings.Join(values, ","), ",") {
		name, params, err := mime.ParseMediaType(strings.TrimSpace(token))
		if err != nil {
			continue
		}
		allowed := true
		if weight, ok := params["q"]; ok {
			q, err := strconv.ParseFloat(weight, 64)
			allowed = err == nil && q > 0 && q <= 1
		}
		switch name {
		case "gzip":
			return allowed
		case "*":
			wildcard = allowed
		}
	}
	return wildcard
}

func (a *Asset) Serve(w http.ResponseWriter, r *http.Request) int {
	h := w.Header()
	h.Set("Cache-Control", a.cacheControl)
	h.Set("Vary", "Accept-Encoding")
	rep := a.plain
	if acceptsGzip(r.Header.Values("Accept-Encoding")) {
		rep = a.gzip
		h.Set("Content-Encoding", "gzip")
	}
	h.Set("ETag", rep.etag)
	for _, val := range r.Header.Values("If-None-Match") {
		for _, tag := range strings.Split(val, ",") {
			tag = strings.TrimSpace(tag)
			if tag == "*" || strings.TrimPrefix(tag, "W/") == rep.etag {
				w.WriteHeader(http.StatusNotModified)
				return http.StatusNotModified
			}
		}
	}
	h.Set("Content-Type", a.mediaType)
	h.Set("Content-Length", strconv.Itoa(len(rep.body)))
	w.WriteHeader(http.StatusOK)
	if r.Method != http.MethodHead {
		_, _ = w.Write(rep.body)
	}
	return http.StatusOK
}
